const only = new Set(process.argv.slice(2));
await fs.mkdir(outDir, { recursive: true });

async function api(route, init) {
  const res = await fetch(`${BASE}${route}`, { ...init, headers: { ...(typeof init?.body === "string" ? { "Content-Type": "application/json" } : {}), ...init?.headers } });
  const data = await res.json();
  if (!res.ok) throw new Error(`${route} ${res.status}: ${JSON.stringify(data).slice(0, 300)}`);
  return data;
}

async function upload(file) {
  const body = new FormData();
  const type = file.endsWith(".mp4") ? "video/mp4" : "image/png";
  body.append("file", new Blob([await fs.readFile(file)], { type }), path.basename(file));
  const res = await fetch(`${BASE}/api/uploads`, { method: "POST", body });
  return (await res.json()).items[0].url;
}

const mediaPath = (url) =>
  url.startsWith("/api/media/out/") ? path.join(root, "data", "media", url.slice(15)) : path.join(root, "data", "uploads", url.slice(19));

/** A still from a clip ("frame:<clip>@<seconds|end>"), cut with the bundled ffmpeg. */
async function frameOf(spec) {
  const [clip, at] = spec.slice(6).split("@");
  const src = await parentFile(clip);
  const out = path.join(outDir, `${clip}-at-${at}.png`);
  const ffmpeg = createRequire(import.meta.url)("ffmpeg-static");
  const seek = at === "end" ? ["-sseof", "-0.06"] : ["-ss", at];
  const run = spawnSync(ffmpeg, ["-v", "error", "-y", ...seek, "-i", src, "-frames:v", "1", out]);
  if (run.status !== 0) throw new Error(`couldn't take a frame of ${clip}: ${run.stderr}`);
  return out;
}

/** A crop of a take, blown up: "crop:<name>@x,y,w,h@WxH" (px of the take; Upscale's enhances start from these). */
async function cropOf(spec) {
  const [name, box, size] = spec.slice(5).split("@");
  const [left, top, width, height] = box.split(",").map(Number);
  const [w, h] = size.split("x").map(Number);
  const out = path.join(outDir, `${name}-crop-${left}-${top}.png`);
  await sharp(await parentFile(name)).extract({ left, top, width, height }).resize(w, h, { kernel: "lanczos3" }).png().toFile(out);
  return out;
}

/** A parent on disk: a kept take ("<id>-<n>.png"), a single output, or a clip. */
async function parentFile(name) {
  if (name.startsWith("frame:")) return frameOf(name);
  if (name.startsWith("crop:")) return cropOf(name);
  if (name === "plate-ext-canvas") return plateCanvas();
  for (const n of [name, name.replace(/-1$/, "")]) {
    for (const ext of [".png", ".mp4"]) {
      const f = path.join(outDir, n + ext);
      if (await fs.stat(f).catch(() => null)) return f;
    }
  }
  throw new Error(`${name} isn't in assets-src/showcase yet; run its job first.`);
}

/** Director's empty alley at 70% on a grey 4:5 border (15% each side, 8% above), for the outpaint. */
async function plateCanvas() {
  const W = 1600;
  const H = 2000;
  const inner = await sharp(await parentFile("dir-plate-g")).resize(Math.round(W * 0.7), Math.round(H * 0.7)).toBuffer();
  const out = path.join(outDir, "plate-ext-canvas.png");
  await sharp({ create: { width: W, height: H, channels: 3, background: { r: 128, g: 128, b: 128 } } })
    .composite([{ input: inner, left: Math.round(W * 0.15), top: Math.round(H * 0.08) }])
    .png()
    .toFile(out);
  return out;
}

/** How each edit uses its parent: Cast and Storyboard frames take it as a reference, the rest edit it. */
function role(job) {
  if (job.video) return { label: "the start frame", role: "subject" };
  if (job.id.startsWith("cs-")) return { label: "the woman", role: "subject" };
  if (job.id.startsWith("sb-") && !job.id.endsWith("-sketch")) return { label: "the reference film still", role: "style" };
  return { label: "the original image", role: "edit-target" };
}

async function run(job) {
  let item;
  const parent = job.parent ? await upload(await parentFile(job.parent)) : null;
  const extra = [];
  for (const p of job.parents ?? []) extra.push({ url: await upload(await parentFile(p.name)), role: p.role, label: p.label });
  if (job.recast) {
    ({ item } = await api("/api/recast", { method: "POST", body: JSON.stringify({ source: parent, start: 0, prompt: job.prompt, label: job.id }) }));
  } else {
    const references = job.parents ? extra : parent ? [{ url: parent, ...role(job) }] : [];
    ({ item } = await api("/api/generations", {
      method: "POST",
      body: JSON.stringify({
        tool: "showcase",
        prompt: "",
        compiledPrompt: job.prompt,
        aspect: job.aspect ?? "4:5",
        count: job.takes ?? 1,
        model: job.model ?? IMAGE,
        refine: false,
        references,
        params: job.video ? { kind: "video", options: { duration: job.video, resolution: job.resolution ?? "1080p", sound: false }, startUrl: parent } : { kind: "image" },
      }),
    }));
  }
  for (;;) {
    await new Promise((r) => setTimeout(r, 3000));
    const { items } = await api(`/api/generations?ids=${item.id}`).catch(() => ({ items: [] }));
    const g = items[0];
    if (!g) continue;
    if (g.status === "error") throw new Error(`${job.id}: ${g.error}`);
    if (g.status !== "done") continue;
    for (const [k, o] of g.outputs.entries()) {
      const src = mediaPath(o.url);
      await fs.copyFile(src, path.join(outDir, `${job.id}${g.outputs.length > 1 ? `-${k + 1}` : ""}${path.extname(src)}`));
    }
    await fetch(`${BASE}/api/generations/${item.id}`, { method: "DELETE" }).catch(() => {});
    console.log(`done ${job.id} (${g.outputs.length})`);
    return;
  }
}

// Parents first: a job waits for the job its parent take comes from.
const jobOf = (parent) => {
  const name = parent?.startsWith("frame:") ? parent.slice(6).split("@")[0] : parent?.startsWith("crop:") ? parent.slice(5).split("@")[0] : parent;
  return JOBS.find((j) => name && (name === j.id || name.startsWith(`${j.id}-`)));
};
const done = new Map();
const produce = (job) => {
  if (!done.has(job.id)) done.set(job.id, (async () => {
    for (const dep of [job.parent, ...(job.parents ?? []).map((p) => p.name)].map(jobOf).filter(Boolean))
      if (!only.size || only.has(dep.id)) await produce(dep);
    await run(job);
  })());
  return done.get(job.id);
};
const wanted = JOBS.filter((j) => !only.size || only.has(j.id));
const results = await Promise.allSettled(wanted.map(produce));
for (const [i, r] of results.entries()) if (r.status === "rejected") console.log(`FAILED ${wanted[i].id}: ${r.reason?.message ?? r.reason}`);
